const t={ui:{fig:"Abb. 1",title:"Tote Bag · Anatomie",svgLabel:"Eine isometrische Zeichnung der Tote Bag und wie sie Schritt für Schritt genäht wird.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Zerlegen",putTogether:"Zusammensetzen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT",cutTitle:"Tasche mit Futter · Zuschnittmaße",cutAlt:"Zuschnittplan für eine Tasche mit Futter: Außenteil aus Baumwoll-Canvas und Futter aus Satin, je 86 × 45 cm mit Faltlinie in der Mitte, dazu zwei Henkel aus Canvas, 100 × 16 cm.",cutCaption:"Alle Zuschnitte mit ihren Maßen – wie in Schritt 1."},stitches:{straight:"Geradstich"},labels:{cm4:"4 cm",cm6:"6 cm",cm8:"8 cm",cm16:"16 cm",cm45:"45 cm",cm86:"86 cm",cm100:"100 cm",fold:"Bruch",outerDuck:"außen · Canvas",liningSatin:"Futter · Satin",strapsDuck:"2 Henkel · Canvas",topstitchEdges:"beide Kanten absteppen",centreCrease:"Mittelbruch",stitchFold:"knapp am Bruch steppen",bottom12:"Boden 12 cm",liftEnds:"beide Enden an den Bruchkanten anheben",foldsIn:"Boden klappt nach innen",centreInside:"Mitte 6 cm nach innen",rightSides:"rechts auf rechts",seam05:"Naht 0,5 cm",layers4:"hier 4 Lagen",turnOut:"auf rechts wenden",openUp:"öffnen",base12:"Boden 12 cm",cornersForm:"Ecken entstehen von selbst",opening8:"Öffnung 8 cm",endsLevel:"Enden bündig mit der Oberkante",turnThrough:"durch die Öffnung wenden",stitchClosed:"zunähen",pushLining:"Futter hineinschieben",topstitch1:"1 cm absteppen"},steps:[{title:"Die fertige Tasche",text:"Eine gefütterte Tote Bag aus drei Teilen: ein Außenteil aus Baumwoll-Canvas, ein Futter aus Satin und zwei lange Henkel. Tippe auf die Tasche, um sie zu zerlegen."},{title:"Zuschneiden",text:"Außenteil: Baumwoll-Canvas, 86 × 45 cm. Futter: Satin, gleich groß. Henkel: zwei Streifen Canvas, 100 × 16 cm.",details:["Schneide aus Baumwoll-Canvas ein Rechteck von 86 × 45 cm für das Außenteil zu und eines in derselben Größe aus Satin für das Futter.","Schneide für die Henkel zwei Streifen Canvas von 100 × 16 cm zu.","Markiere auf Außenteil und Futter quer in der Mitte die Faltlinie, 43 cm von jeder kurzen Kante entfernt – sie wird zum Boden der Tasche.","Die Nahtzugabe beträgt bei dieser Tasche überall 0,5 cm."]},{title:"Henkel nähen",text:"Falte den Streifen zur Hälfte und bügle ihn, klappe ihn auf, falte beide Kanten zum Bruch und falte noch einmal: ein 4 cm breiter Henkel aus vier Lagen. Steppe beide Kanten ab.",details:["Falte einen Streifen der Länge nach zur Hälfte, links auf links, und bügle einen Bruch ein.","Klappe ihn wieder auf. Falte beide Längskanten nach innen, sodass sie sich am Bruch treffen, und bügle noch einmal.","Falte ihn entlang des ersten Bruchs zur Hälfte. Der Henkel ist jetzt 4 cm breit und vier Lagen dick, alle offenen Kanten liegen innen.","Steppe beide Längskanten knappkantig mit Geradstich ab. Nähe so zwei Henkel."]},{title:"Boden formen",text:"Bügle in der Mitte einen Bruch ein und klappe das Teil wieder auf. Miss zu jeder Seite 6 cm ab, falte an jeder Linie und steppe knapp am Bruch: zwei abgesteppte Bruchkanten, ein 12 cm breiter Boden.",details:["Falte das Außenteil quer in der Mitte und bügle einen Bruch ein. Klappe es wieder auf.","Miss vom Mittelbruch aus 6 cm zu jedem Ende hin ab und zeichne eine Linie über die ganze Breite des Teils.","Falte entlang der ersten Linie, rechts auf rechts, und steppe knapp am Bruch. Klappe das Teil auf, dann falte und steppe die zweite Linie genauso.","Die beiden abgesteppten Bruchkanten, 12 cm voneinander entfernt, sind die Kanten des Bodens; der Mittelbruch ist seine Mitte."]},{title:"Boden einschlagen",text:"Hebe beide Enden an den abgesteppten Bruchkanten hoch und führe sie zusammen: Der Boden klappt nach innen, und der Mittelbruch wandert 6 cm nach innen. Leg alles flach hin.",details:["Leg das Teil mit der rechten Seite nach oben hin und hebe beide Enden an, sodass es an den beiden abgesteppten Bruchkanten abknickt.","Führe die Enden zusammen. Der 12 cm breite Boden klappt nach innen, und der Mittelbruch liegt innen, 6 cm hoch zwischen den Lagen – wie der Boden einer Papiertüte.","Leg das Teil flach hin, rechts auf rechts. Die abgesteppten Bruchkanten bilden jetzt die Unterkante, und das gefaltete Teil ist 6 cm kürzer, als wenn du es einfach zur Hälfte faltest."]},{title:"Seiten nähen",text:"Lass den Boden eingeschlagen und nähe beide Seiten mit 0,5 cm Nahtzugabe – durch alle Lagen, unten sind es vier.",details:["Fixiere die Seiten mit Klammern, damit der eingeschlagene Boden an seinem Platz bleibt.","Nähe beide Seitennähte 0,5 cm von der Kante entfernt bis ganz nach unten. Unten geht die Naht durch vier Lagen – Vorderteil, die beiden Hälften des eingeschlagenen Bodens und Rückteil. Lass die Oberkante offen."]},{title:"Wenden",text:"Wende das Außenteil auf rechts und öffne es: Der Boden entfaltet sich zu einer 12 cm breiten Standfläche, und die Ecken entstehen von selbst.",details:["Wende das Außenteil durch die obere Öffnung auf rechts.","Öffne es und drück den Boden nach außen. Der eingeschlagene Boden entfaltet sich zu einer flachen, 12 cm breiten Standfläche, und wo die Seitennähte ihn gefasst haben, entstehen von selbst saubere Ecken – zusätzliche Nähte an den Ecken sind nicht nötig."]},{title:"Futter nähen",text:"Nähe das Satinfutter genauso – lass aber in einer Seitennaht eine 8 cm lange Wendeöffnung. Durch sie wendest du später die Tasche.",details:["Nähe das Futter genau wie das Außenteil: Bügle den Mittelbruch ein, steppe die beiden Bruchkanten 6 cm davon entfernt ab und schlag den Boden nach innen ein.","Nähe beide Seitennähte 0,5 cm von der Kante entfernt – lass aber auf einer Seite eine 8 cm lange Wendeöffnung, weit unten, direkt über dem eingeschlagenen Boden. Durch sie wendest du die Tasche.","Lass das Futter auf links."]},{title:"Außenteil und Futter verbinden",text:"Stecke die Henkel 6 cm von der Mitte entfernt ans Außenteil. Schieb das Außenteil in das auf links gedrehte Futter und nähe rundherum an der Oberkante entlang.",details:["Wende das Außenteil auf rechts.","Stecke einen Henkel an die vordere Oberkante: die Enden bündig mit der offenen Kante, 6 cm von der Mitte entfernt, die Schlaufe hängt nach unten über die Tasche. Mach dasselbe auf der Rückseite.","Schieb das Außenteil samt Henkeln in das auf links gedrehte Futter, sodass die rechten Seiten aufeinanderliegen. Leg die Seitennähte und die Oberkanten genau aufeinander.","Nähe einmal rundherum an der Oberkante entlang, 0,5 cm von der Kante entfernt."]},{title:"Wenden und absteppen",text:"Wende die Tasche durch die Öffnung und nähe die Öffnung zu. Schieb das Futter hinein und steppe die Oberkante rundherum 1 cm von der Kante entfernt ab.",details:["Zieh die ganze Tasche durch die Öffnung im Futter auf rechts.","Schlag die offenen Kanten der Öffnung nach innen ein und nähe sie knappkantig zu.","Schieb das Futter nach unten in die Tasche hinein und bügle die Oberkante flach.","Steppe rundherum an der Oberkante ab, 1 cm von der Kante entfernt. Deine Tote Bag ist fertig!"]}],legend:[{title:"Außenteil",text:"Baumwoll-Canvas · Zuschnitt 86 × 45 cm, am Boden gefaltet"},{title:"Futter",text:"Satin · Zuschnitt 86 × 45 cm, wie das Außenteil"},{title:"Henkel ×2",text:"Zuschnitt 100 × 16 cm · vierfach gefaltet auf 4 cm"},{title:"Boden",text:"zwei Bruchkanten, je 6 cm neben dem Mittelbruch abgesteppt und vor den Seitennähten nach innen eingeschlagen → eine 12 cm breite Standfläche, die Ecken entstehen von selbst"},{title:"Steppnaht",text:"1 cm von der Oberkante · alle Nähte 0,5 cm"}]};export{t as default};
